insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('1ccbf131-6df9-4829-afc6-793d8a586ba6', 'ja', '彼女がこちらにほほえみます。最初のひと言を考え始めてしまいます。一番良い動きはどれですか？', '["何を言うかリハーサルしてから行く", "磨いたひと言がなくても、すぐに歩いていく", "確認のために、もう一度目が合うまで待つ"]'::jsonb, 'すばやく動けば、迷いがふくらむのを止められます。彼女に気づいてから3秒以内に動きましょう。')
