insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('21c693ec-ce2c-4a1c-b6a4-e5c07cc9e39f', 'ja', '声が小さすぎて、彼女は聞き取れなかったところを推測で埋めなければなりません。これは何を生みますか？', '["すぐに生まれる、強く惹かれる気持ち", "環境に完璧に合った存在感", "ミステリアスで、興味をそそる雰囲気", "なめらかな流れを損なう引っかかり"]'::jsonb, '聞き取りにくさは、やり取りに不要な緊張を加えます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('21ca0984-0243-415e-ab95-8d472e631a12', 'ja', 'テラス席のあるカフェで、女性に近づいています。余裕を伝える体の動きは、どれですか？', '["肩を丸めた、せかせかした速い足取り", "腕を体の横に固めた、ぎこちない歩き方", "腕を自然に振り、背筋を伸ばした、安定したペース", "地面を見つめながらの、ためらいがちな足取り"]'::jsonb, 'リラックスした動きは安全を伝え、彼女にとってやり取りを楽なものにします。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('243e45da-4e6e-4747-bd72-4c71c92d582b', 'ja', '彼女を見かけますが、今日の服装はいまひとつです。次にどうするべきですか？', '["それでも声をかける", "見送る。見た目がチャンスを損なうから", "準備が整うまで待つ", "目は合わせるが、言葉はかけない"]'::jsonb, '声をかけるのを完璧な条件のときだけに限ると、場数が踏めません。声は、いつでもかけられます。')
