insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('24ae814b-7816-4ac9-af4c-f56e4e9d8de9', 'ja', 'さりげないひと言は、なぜ割り込まれた感じが少ないのですか？', '["沈黙を避けるから", "自信を示すから", "二人がすでに共有しているその場面に、加わるものだから"]'::jsonb, '同じ状況を共有していると、話しかけられることが自然に感じられ、応じやすくなります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('24ebc378-571a-47ca-a34d-406494e05bf1', 'ja', '彼女がノートに何かをスケッチしているのを見かけます。好奇心が伝わるひと言は、どれですか？', '["「アーティストっぽいですね」", "「ここ、座ってもいいですか？」", "「才能がありますね。見ればわかります」", "「何を描いているんですか？すごく細かいですね」"]'::jsonb, '彼女の経験への好奇心は、下心なしに、本物のつながりを招きます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('26e9ec88-6ad1-419a-a087-c91efb8998d2', 'ja', '長い目で見て、声をかけることを続けやすくする習慣は、どれですか？', '["毎日、人と話すこと", "準備ができたと感じるまで待つこと", "日常の場所で人と関わること"]'::jsonb, '日ごろから人と関わっていると、プレッシャーが下がり、やり取りが楽に感じられます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2726ad43-344c-4ec6-a996-4df4d37978f4', 'ja', '個性的なアクセサリーを身につけた女性を見かけます。好奇心を引くために、最初に何を言えますか？', '["「それ、どこで買ったんですか？」", "「身につけているそれについて、ちょっと聞きたいことがあるんです」", "「それ、いいですね。好きです」", "「このあたりの方ですか？」"]'::jsonb, '前置きが、質問を明かす前に好奇心を生みます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('29a122e7-d801-4e7c-bf05-40a46aba0960', 'ja', '彼女は一人で列に並んでいます。彼女の意見を引き出したいと思います。一番良い最初のひと言はどれですか？', '["「こんにちは。今日はどんな一日ですか？」", "「ちょっと聞いてもいいですか。コーヒー派ですか、紅茶派ですか？」", "「ここの季節限定のドリンクと定番、どちらがいいと思いますか？」"]'::jsonb, '議論や迷いごとの形にすると、彼女の意見を招くことになり、大切にされ、加わっていると感じてもらえます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2ada2eb4-7e4e-4ea9-b9d1-7cde29ea6304', 'ja', '彼女はほとんど振り向かず、平板な「どうも」を返します。これは何を示していますか？', '["内気さ", "好奇心", "どちらともつかない関心", "冷たい反応"]'::jsonb, '最小限の反応は、引くべきだという意味です。すっきりと切り上げましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2b69af0f-cead-4bcb-8f8d-580b110d13f2', 'ja', '冷たいサインを最もはっきり示しているのは、どれですか？', '["短くほほえむこと", "質問に答えること", "体をそむけること", "礼儀として笑うこと"]'::jsonb, '閉じた体の向きは、関心が離れていることを示します。立ち去りましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2d63f1fb-98b5-4678-aec8-6b0c2abded25', 'ja', '彼女はこちらを向き、温かくほほえみ、ていねいに答えてくれますが、友人たちのほうを何度も見ています。', '["受け入れのサイン。友人を気にしていても、質問してくるのは関わっている証拠", "礼儀のサイン。感じはいいが、何度も視線を向けるのは、注意が分散している証拠", "どちらともつかないサイン。友人の様子を見ているだけなので、ふつうに続ける"]'::jsonb, '質問は礼儀としての関わりを示していますが、注意は完全にはこちらにありません。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2f7b8ecd-021a-40d3-aea3-50d2530f7f6e', 'ja', '彼女は温かく答えてくれますが、スマホをスクロールし続けています。どう受け取るべきですか？', '["内気なのだ", "受け入れている", "気は散っているが、関心はある", "礼儀正しくしているだけだ"]'::jsonb, '注意が分かれているのは、たいてい、関わっているのではなく礼儀です。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('2fa1ad2f-3496-4f7e-b850-7253ba88fd6b', 'ja', '彼女は最初のひと言に笑い、体をまっすぐこちらに向けますが、腕を組みます。何が起きていますか？', '["受け入れのサイン。腕は組んでいても、笑いと体の向きが関心を示している", "礼儀のサイン。閉じたボディランゲージを伴う作り笑いは、関心がないという意味", "入り混じったサイン。笑いと体の向きは受け入れだが、組んだ腕は迷いを示している"]'::jsonb, '笑いは心地よさを、組んだ腕はためらいを示しています。軽い調子で続けましょう。')
