insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3583c492-59dd-4eb4-a7c9-c98966901e7d', 'ja', '彼女が個性的なコーヒーカップを持っているのを見かけます。好奇心を引くために、最初に何を言えますか？', '["「そのコーヒーカップについて、どうしても聞きたいことがあるんです」", "「そのカップ、どこで買ったんですか？」", "「そのカップ、楽しい感じですね」", "「ここにはよく来るんですか？」"]'::jsonb, '前置きが、質問を明かす前に好奇心を生みます。')
