insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('36134173-386a-4742-a375-45b16eeb371f', 'ja', '空気をしっかりリードするには、何が必要ですか？', '["続けていいという許可やサインを、彼女がくれるのを待つこと", "彼女の現実に加わるのではなく、自分で話題を決めること", "彼女がリードするのを待たずに、やり取りを前へ進めること"]'::jsonb, '空気をリードするとは、話題と展開を導くことです。')
