insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('365d84da-247e-427e-a603-8e7d2900f73f', 'ja', '彼女は感じよく応じてくれますが、「そろそろ行かないと」と言います。これは何ですか？', '["やわらかい境界線を伴う礼儀のサイン。関わってはいるが、時間が限られていると伝えている", "受け入れのサイン。感じのいい反応は関心の表れで、「行かないと」は礼儀にすぎない", "入り混じったサイン。関わり方と「行かないと」という言葉が食い違っている"]'::jsonb, '彼女は気を配りながら、限りがあることを伝えています。それを受け止めて、礼儀正しく締めくくりましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3669c3ab-5f36-42cb-932f-6277589d1d8e', 'ja', '彼女の最初の反応を読み取ることは、なぜ大切なのですか？', '["彼女を、無理にでも受け入れる気にさせるから", "二人ともにとって、やり取りを心地よく保つから", "彼女のスペースとサインを尊重することになるから", "まだ開かれていない一線を越えるのを防ぐから"]'::jsonb, '正確に読み取ることで、お互いの心地よさと落ち着きが保たれます。')
