insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3717fc9d-129b-426e-a329-a0e904cfd1e1', 'ja', '彼女は短く答え、視線をそらし、体重を移し替えます。次にどうするべきですか？', '["短く切り上げ、感じよく立ち去る", "彼女を引き込むために、さらに質問を重ねる", "惹かれる気持ちを築くために、距離を縮める", "打ち解けてもらうために、彼女を褒める"]'::jsonb, 'どちらともつかない礼儀のサインは、彼女の心地よさを尊重して、ペースを落とすか、引くべきだという意味です。')
