insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3763474f-7119-463b-a740-ab5dd1bb8606', 'ja', 'カフェで本を読んでいる彼女に声をかけます。場の空気をしっかり保てるひと言は、どれですか？', '["「お邪魔してすみません。ひと言ごあいさつしたくて」", "「この席、空いていますか？」", "「その本、面白そうですね。どんな話なんですか？」", "「すみません、少しお話ししてもいいですか？」"]'::jsonb, '応じてもらえる前提でまっすぐ話しかけることが、謝ることなく、場の空気をリードします。')
