insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('38ade8d0-fc3e-4396-9791-5b19775afa46', 'ja', '開けた場所で彼女に声をかけます。避けるべきことは何ですか？', '["開いた姿勢で、適度な距離を空けて止まること", "彼女が立ち去れる通り道をふさぐこと", "見える位置の、斜め45度から近づくこと", "約1メートルのスペースを保つこと"]'::jsonb, '出口をふさぐことは、開けた場所であっても、不快感を引き起こします。')
