insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3a61650f-61dd-4d87-b302-9c1fad8a6217', 'ja', '場の空気をつくるうえで、遊び心はなぜ大切なのですか？', '["プレッシャーを減らし、やり取りをまじめではなく楽しいものに感じさせるから", "遊び心のある空気は、前向きな感情の体験を通じて、惹かれる気持ちを生むから", "こちらがリラックスしていることを伝えるから", "上のすべて"]'::jsonb, 'どれも正しいです。遊び心は、プレッシャーを減らし、前向きな感情を生み、リラックスしていることを伝えます。')
