insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3aa54f55-0812-4c14-be64-8fed1f814fb4', 'ja', '受け入れと礼儀を最もよく見分けられるサインは、どれですか？', '["笑顔", "アイコンタクト", "質問を返してくること", "うなずき"]'::jsonb, '同じだけ返ってくることは、ほかのものよりも、関心をはっきり示します。')
