insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3b44889c-1e0c-4a51-8846-e7d4ea05c95b', 'ja', '列に並んでいる彼女に声をかけます。彼女は「実は急いでいるんです」と言います。一番良い対応はどれですか？', '["「大丈夫ですよ。ひと言ごあいさつしたかっただけなので」と言って、さらりと立ち去る", "邪魔をしたことを謝って、身を引く", "彼女の言葉を無視して、かまわず話し続ける"]'::jsonb, '会話を無理に続けることも、謝ることも避けましょう。軽く受け止めて、次へ進みます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3c06a35a-c102-4ca8-bce5-02e0afa2b5a6', 'ja', 'クラブで、彼女と一緒に静かな場所へ移動しました。次はどうしますか？', '["会話を続け、別の日に会おうと提案する", "流れが良いうちに、今、連絡先を聞く", "一緒に別の場所へ移ろうと提案する", "状況と彼女のサインに応じて、LINEを聞くか、一緒に別の場所へ移ろうと提案する"]'::jsonb, '流れが良いときは、次の一歩に進みましょう。連絡先を交換するか、彼女のサインが「はい」と言っているなら、別の場所で続けようと提案します。')
