insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3c98c86a-c4c9-43a5-be53-6cad77bf34c5', 'ja', 'やり取りは、どんなときに切り上げるべきですか？', '["冷たいサインが出ているとき。最小限の反応、閉じた体、そむけた向き", "礼儀のサインが続くとき。短い返事、返ってくるものが少ない", "時間の制約や状況から、続けるのがふさわしくないとき", "上のすべて"]'::jsonb, '相手が乗ってきていないときは、すっきりと切り上げることが、心地よさと自分の軸を守ります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3caf0039-8d00-42c1-8c5a-9b57ae2ac717', 'ja', '彼女は「実は今、手が離せなくて」と言いますが、ほほえんだまま、こちらを向いています。', '["受け入れのサイン。笑顔は言葉に勝る", "礼儀のサイン。境界線を、丁寧に伝えている", "入り混じったサイン。軽く押してみる", "冷たいサイン。どんな境界線も拒絶と同じ"]'::jsonb, '温かさを伴ったはっきりした境界線は、礼儀正しく引いているということです。')
