insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3dfb88ca-871e-4a7e-b233-6335a1bd949a', 'ja', '話していると、彼女の友人が近くで様子をうかがっているのに気づきます。一番良い動きはどれですか？', '["友人を無視して続ける", "注意を引こうと張り合う", "友人も少し会話に加えてから、あらためて様子を見る", "すぐに距離を縮める"]'::jsonb, '巻き込むことで、その場の緊張がやわらぎ、主導権も保たれます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('3ebc28c1-d1f2-41ee-a393-af6d74a978a9', 'ja', '彼女は笑いますが、体をそむけ続けています。より重要なのは、どれですか？', '["彼女の笑い", "こちらの最初のひと言", "彼女のボディランゲージ", "その場の環境"]'::jsonb, '手がかりが食い違うときは、体のサインを信頼しましょう。彼女が体をそむけるなら、スペースを空けるか、引きましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('40d53e0a-03ba-435a-8d62-e1fcb096eded', 'ja', 'さりげないひと言を、自然で受け取りやすいものにするのは何ですか？', '["気の利いたことや、感心されることを言うこと", "二人が共有している環境や、その瞬間", "完璧なタイミング"]'::jsonb, '同じ状況を共有していると、話しかけられることが自然に感じられ、応じやすくなります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4232f870-74a7-4557-9e29-70a586b48204', 'ja', 'バーで彼女を見かけます。ストレートな声のかけ方は、どれですか？', '["会話を始めるために、音楽や飲み物についてひと言言う", "目を合わせて、ほほえむ", "「つい目を引かれて、ごあいさつしたくて来ました」"]'::jsonb, 'ストレートなひと言は、恋愛的な関心を、最初にはっきり伝えます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('478e1b59-9821-4b03-8744-b950a6269270', 'ja', 'ヴィンテージの腕時計をした女性を見かけます。相手を引き込むひと言は、どれですか？', '["「こんばんは。今夜の調子はどうですか？」", "「素敵ですね」", "「お仕事は何をしているんですか？」", "「その時計、何か歴史がありそうですね」"]'::jsonb, '具体的な推測は、彼女が自分のこととして関わり、答えることを求めます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('48e4513c-c89e-4a8b-99e3-d70a28ea7193', 'ja', '列に並んでいます。「この行列にしては、落ち着きすぎていませんか」と言うと、彼女が笑います。何がうまくいっていますか？', '["共有している状況に触れた", "遊び心のある対比をつくった", "話していいか、許可を求めた"]'::jsonb, '共有している状況に遊び心が加わると、抵抗がすばやく下がります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4de13376-2210-4667-8d5f-ae59a38657c2', 'ja', '一度のはっきりした行動で関心を確かめることは、なぜ、だらだら続けるより良いのですか？', '["やり取りを短くするから", "リードする姿勢を示すから", "断られるのを防ぐから", "彼女に、はっきりした状況と、選ぶ主導権を渡すから"]'::jsonb, 'はっきりしたひと言は、その礼儀正しさが関心なのか、ただの礼儀なのかを明らかにして、あいまいさを取り除きます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4ef57d59-ef61-4420-92a6-2b920652d1b8', 'ja', '意見を聞くひと言は、なぜ人に「大切にされている」と感じさせるのですか？', '["彼女の視点を求めることで、その判断が大切だとはっきり伝えているから", "意見を聞くことは、感情を読み取る力と人付き合いのスキルを示すから", "人は、聞くことよりも、自分について話すことを楽しむから"]'::jsonb, '人は、自分の視点が大切にされると、ぱっと明るくなります。大切にされることが、関わりを生みます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('4fe08740-af66-4896-aa93-6a50f2a41020', 'ja', '彼女は「実はちょうど帰るところで」と言いますが、その場にとどまり、質問を続けてきます。', '["礼儀正しく引いている", "受け入れ寄りの、入り混じったサイン", "人当たりよくやわらげた、冷たいサイン", "はっきりした拒絶"]'::jsonb, 'とどまっていることと、続く好奇心は、事情はあっても心を開いていることを示します。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5027deaf-2157-42e1-b4db-138c9801e876', 'ja', '彼女はほほえみ、好意的に応じてくれますが、「実は試験勉強中なんです」と言います。', '["受け入れのサイン。勉強に触れてはいても、好意的な反応は関心の表れ", "礼儀正しいお断り。感じよくしながら、勉強を理由に境界線を引いている", "テスト。粘るか、彼女の優先事項を尊重するかを見ている"]'::jsonb, '好意的なトーンは、礼儀の場合もあります。口にされた優先事項は、境界線です。「がんばってください」と伝えて、立ち去りましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('50916cec-9c9c-486c-b266-a45065ff3ea2', 'ja', '彼女は熱のこもった反応を返し、さらに質問もしてきますが、スマホを何度も確認しています。', '["受け入れのサイン。スマホを見ていても、言葉での関わりは本物の関心を示している", "礼儀のサイン。スマホの確認は言葉の温かさと食い違っていて、注意が分かれている", "入り混じったサイン。言葉のサインは受け入れだが、行動は気が散っていることを示している"]'::jsonb, '入り混じったサインには、相手の反応を見て合わせることが必要です。少しだけ続けて、注意が戻ってくるかどうかを確かめましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('51786178-0f86-4cb1-b4bd-0b3e68a87f9e', 'ja', '礼儀を関心と読み違えることは、なぜ危ういのですか？', '["やり取りのペースを落とすから", "彼女に、望まないプレッシャーをかけるから", "声のかけ方を、大胆に感じさせるから"]'::jsonb, '彼女の心地よさが最優先です。続けるか、引くかを決めるために、サインを使いましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('51944bdf-42d0-42e5-b902-ff0f21714718', 'ja', '彼女は温かく関わり、笑い、質問もしてきますが、「実は彼氏がいるんです」と言います。', '["受け入れのサイン。関わり方は関心の表れで、彼氏の話はテスト", "礼儀のサイン。温かい関わりは親しみで、彼氏の話ははっきりした境界線", "入り混じったサイン。関心は見せているが、交際状況が葛藤を生んでいる"]'::jsonb, '彼女は親しみを見せていただけで、恋愛として受け入れていたわけではありません。彼氏の話は、はっきりした境界線です。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('51f130a3-2032-4c6f-b654-83d546e7b8aa', 'ja', 'パーティーで、彼女は礼儀正しいのですが、関心があるのかどうか分かりません。役立つひと言は、どれですか？', '["「飲み物を取ってきます。一緒にどうですか？」", "「このパーティー、ちょっと退屈ですね」", "「ほかの方ともお話ししてきてください」", "「友人たちに紹介しますよ。来ませんか？」"]'::jsonb, 'はっきりした誘いは、動く、加わる、続けるといった意思を、プレッシャーをかけずに確かめます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('520ac978-94f9-404d-aabe-55099eebb89e', 'ja', '彼女が、留学していたことを話します。下心のない返しは、どれですか？', '["そこで何が一番好きだったかを、心を込めて尋ねる", "惹かれる気持ちを築くために、見た目を褒める", "すぐにLINEを聞き出そうとする", "自分の実績だけを話す"]'::jsonb, '彼女の話への純粋な関心は、「追いかけられている」ではなく、「ちゃんと見てもらえている」と感じさせます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('530f7582-4d63-4e0c-bede-bf88b8fdbd71', 'ja', '「少ししかいられないんですが」と伝えることは、なぜプレッシャーを減らすのに役立つのですか？', '["知らない人との終わりの見えない会話に、縛られるわけではないと分かるから", "彼女の時間を尊重し、無駄にしないことを示すから", "限られた時間が、緊急性を生むから"]'::jsonb, '時間の制限は、すぐに立ち去ることを伝え、彼女の警戒を下げます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('55289809-9c93-4056-aed5-077280b1ae2f', 'ja', 'ストレートなひと言の、一番の強みは何ですか？', '["声をかけるときに、自分がより自信を持てること", "大胆さによって、惹かれる気持ちを高めること", "すぐに意図を伝えることで、あいまいさを取り除くこと"]'::jsonb, 'ストレートに伝えることで、探り合いがなくなり、すぐに意図が伝わります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5645caed-20b5-412a-abcf-de263b1e3c46', 'ja', '彼女はスマホをスクロールしています。最初のひと言がうまくいくには、どうである必要がありますか？', '["礼儀正しいこと", "もっと大きな声であること", "面白いこと", "短く、切れ味があること"]'::jsonb, '最初のひと言は、彼女がそれまでしていたことよりも面白くなければなりません。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('59132ed6-d432-4176-9308-5f83ffeb2e2c', 'ja', '声をかけるとき、笑顔はなぜ男性を誤解させやすいのですか？', '["笑顔は、いつでも惹かれているサインだから", "笑顔は、人付き合いの基本的な礼儀だから", "男性は、感情的な温かさを関心だと思い込むから", "両方。笑顔は礼儀であることが多く、男性は温かさを関心と読むから"]'::jsonb, '笑顔は礼儀であることが多く、男性はよく、温かさを「惹かれている」と解釈します。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5a89ed7d-2ccb-4fb2-ad5a-c8b0d73aab44', 'ja', '最初のひと言に、彼女は礼儀正しく、でも短く応じます。空気をリードし続けられるのは、どれですか？', '["先へ導くために、引き込む質問をもう一つする", "邪魔をしたことを謝って、立ち去る", "彼女が質問してくるのを待つ", "彼女の低いエネルギーに合わせて、どちらともつかない態度でいる"]'::jsonb, '方向を決めるのは自分です。彼女が引くのに合わせるのではなく、リードし続けましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5b1abc4a-c6ad-4dd2-b4a0-e8c4cf55f119', 'ja', '脳は、なぜ言葉より先に体の動きを読むのですか？', '["言葉の内容を先に処理するから", "動きは、意図と安全を本能的に伝えるから", "なめらかな動きは、心地よさを示すから", "こわばった動きは、不安を発するから"]'::jsonb, 'リラックスした動きは安全を伝え、彼女にとってやり取りを楽なものにします。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5b40af44-7fc8-4e4e-93fe-427ce1753d12', 'ja', 'バーで声をかけます。彼女はほとんど振り向かず、平板に「どうも」と言い、こちらが話しているあいだ店内を見回しています。', '["礼儀のサイン。最低限の礼儀を見せている。短くするか、切り上げる", "冷たいサイン。はっきり関心がない。すぐに引く", "テスト。エネルギーが低くても自分の軸を保てるかを見ている"]'::jsonb, '閉じたボディランゲージは、返事よりも重みがあります。一歩引いて、落ち着いて立ち去りましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5bd1ec51-0293-467c-b328-37d4c947a52a', 'ja', '二人とも、カフェの長い列に並んでいます。さりげないひと言になるのは、どれですか？', '["ここでいつも何を頼むのかを聞く", "笑顔を褒める", "列の進みが遅いことに触れる", "すぐに自己紹介をする"]'::jsonb, '共有している状況は、自然で、プレッシャーの少ない入り口になります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5c6d17f6-baa9-4899-916b-fc9639e67f2c', 'ja', '彼女が、とても特徴的なケースをつけたスマホを持っています。好奇心を引くために、最初に何を言えますか？', '["「そのスマホケース、どこで買ったんですか？」", "「そのスマホ、気に入っていますか？」", "「そのスマホケース、面白いですね」", "「そのスマホケースについて、聞きたいことがあるんです」"]'::jsonb, '前置きが、質問を明かす前に好奇心を生みます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5e1e4ba0-77d1-47d1-b948-830f42c9bfc1', 'ja', 'やり取りの中で早口になると、何が起こりますか？', '["聞き取りにくくなる", "緊張が伝わる", "リズムが崩れる", "上のすべて"]'::jsonb, '言葉が急ぐと、聞き取りにくくなり、緊張したエネルギーが表に出ます。ペースを落としましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5e77a13d-51fd-4fc8-8b20-e153be35f50a', 'ja', '礼儀正しい反応は、たいてい何を示していますか？', '["関心はあるが、こちらの自信と軸を試している", "関心はまったくないが、角を立てないように親切にしている", "まだ決めかねているか、心を開ききっていない。ゆっくり進めるか、切り上げる"]'::jsonb, '礼儀正しい反応は、決めかねているか、閉じているという意味です。次のサインを注意深く読み取りましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('5f79a125-3233-4761-a27a-0c3df5b785b6', 'ja', '時間の制限を伝えると、何が起こりますか？', '["やり取りに出口ができるので、プレッシャーが下がる", "長く付き合わされることはないと分かって、彼女がリラックスする", "緊急性が生まれ、彼女がそのやり取りをより高く評価する"]'::jsonb, '制限があると、「抜け出せなくなる」という不安がなくなり、安心感が増します。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('60bdd118-0868-4732-a177-bad97e1d37de', 'ja', '彼女の手首に、小さなタトゥーが見えます。好奇心を引くために、最初に何を言えますか？', '["「かっこいいタトゥーですね。何の柄ですか？」", "「そのタトゥー、素敵ですね」", "「そのタトゥーのこと、どうしても聞きたくて」", "「ほかにもタトゥーがあるんですか？」"]'::jsonb, '前置きが、質問を明かす前に好奇心を生みます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('610a475a-54e4-4882-b442-6ebc0faac3a8', 'ja', '二人とも、カフェの長い列に並んでいます。一番うまくいくさりげないひと言は、どれですか？', '["「本当にきれいですね。どうしても声をかけたくて」", "「LINE、教えてください」", "「今日のこの列、すごいですね」", "「コーヒーが必要そうな顔をしていますね」"]'::jsonb, 'その場の状況についてのひと言は、自然に感じられ、プレッシャーを減らします。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('611e32cc-c038-42d3-a1ce-086d78cbcd68', 'ja', '彼女は短く答え、目をそらし、足を踏み替えます。一番良い対応はどれですか？', '["もっと踏み込んだ質問をする", "軽くからかう", "すっきりと切り上げる", "エネルギーを上げる"]'::jsonb, '礼儀正しく引いているサインは、立ち去るときだという意味です。押さずに、すっきりと切り上げましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('61e8562c-6ad4-4305-bf8f-d44fe44652ab', 'ja', '好奇心から声をかけるための、中心となる考え方の切り替えは何ですか？', '["「ここから何か得られるだろうか」", "「この人は、自分にとって興味深い人だろうか」", "「どうすれば、すばやく彼女を感心させられるだろうか」", "「これはデートにつながるだろうか」"]'::jsonb, '彼女の世界への関心は、下心を取り除き、本物の関わりを可能にします。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6212b078-0050-447a-bf0f-ff2070f3f00c', 'ja', 'カフェの列で声をかけます。彼女は短くほほえみ、「うん」と言って、スマホに目を落とします。', '["どちらともつかないサイン。気は散っているが、粘れば応じてくれるかもしれない", "礼儀のサイン。こちらを認めはしたが、すぐに注意をよそへ向けた", "冷たいサイン。スマホを見るのは、意図的に退けるサイン"]'::jsonb, '彼女はこちらを認めたうえで、境界線を引きました。引き延ばさずに、引きましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('624f3918-37e1-4cec-8932-2afa6e870e81', 'ja', '二人とも、雨の中、バス停で足止めされています。プレッシャーを減らす最初のひと言は、どれですか？', '["「雨の中でも、本当におきれいですね」", "「LINE、教えましょうか？」", "「傘に入れてもらえますか？」", "「ひどい天気ですね。バス、また遅れているんでしょうか？」"]'::jsonb, 'その場で共有している体験が、会話を自然に始めさせてくれます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('645565d5-3468-40e0-a262-b135680333a7', 'ja', '彼女のバッグに、マニアックなフェスのキーホルダーがついているのを見つけます。好奇心が伝わるひと言は、どれですか？', '["「かっこいいキーホルダーですね」", "「個性のあるバッグですね」", "「イベントによく行くんですか？」", "「そのフェス、行ったんですか？すごいって聞きました」"]'::jsonb, '彼女の経験への好奇心は、下心なしに、本物のつながりを招きます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('66e6b51f-4377-41cc-af99-be7fc8703380', 'ja', '昼間のジムで声をかける場面です。彼女はセットの合間です。一番良い動きはどれですか？', '["彼女がトレーニングを完全に終えるまで待ってから、声をかける", "視界に入り、目を合わせ、ほほえんで、休憩のあいだに声をかける", "自然なきっかけをつくるために、補助やフォームのチェックを頼む", "ジムはふさわしくないので、見送る"]'::jsonb, 'セットの合間は、短いチャンスです。驚かせないように、見える位置から近づき、目を合わせましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6854fe8c-37a2-4b05-abb5-8e28e81f85df', 'ja', '路上で声をかけます。彼女は礼儀正しいのですが、関心があるのかどうか分かりません。彼女の関心の度合いをはっきりさせるのに役立つひと言は、どれですか？', '["「どのみち、こっちへ歩くんです。一緒にどうですか？」", "「それで、どちらへ行くところですか？」", "「今度、コーヒーでもどうですか？」", "「面白そうな人ですね」"]'::jsonb, '一緒に動く誘いや先の約束への誘いは、褒め言葉ではなく、行動を通じて関心を確かめます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6ae58be8-fa28-4df9-982d-734c8bf6bc6b', 'ja', 'その瞬間が過ぎ、すぐに後悔を感じます。原因は何ですか？', '["挑戦して断られたこと", "彼女に関心がなかったこと", "どこにもつながらなかった会話", "行動せずに、チャンスを見送ったこと"]'::jsonb, '後悔は、失敗した挑戦からではなく、逃したチャンスから生まれます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6c9441f0-7531-4148-a292-db648381ccf0', 'ja', '書店にいます。意見を聞くひと言として、何が言えますか？', '["「本はプレゼントとしてありかどうか、意見を聞かせてほしいんです」", "「小説のコーナーはどこか、ご存じですか？」", "「すみません、何か面白いものを読んでいるんですか？」"]'::jsonb, '彼女の判断が必要だという形にすると、すぐに「大切にされている」と感じてもらえます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6d84a13d-95e6-437d-9368-891c4d42990a', 'ja', 'たいてい受け入れを示している手がかりは、どれですか？', '["質問を返してくること", "こちらに体を向けていること", "質問に答えること", "リラックスした姿勢"]'::jsonb, '質問を返してくることと体の向きは、関心を示しています。続けていい青信号として受け取りましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6e852fdc-853b-47ca-bd28-81f1c157b93e', 'ja', 'ストレートなひと言が一番うまくいくのは、どんな環境ですか？', '["バー、クラブ、パーティー、交流イベント", "静かな図書館やオフィス", "混雑する時間帯のスーパー", "通勤中の公共交通機関"]'::jsonb, '出会いが期待されている社交の場では、恋愛的な意図も自然に感じられます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('6ead40bd-0dee-4b4c-935e-8cf034256a37', 'ja', 'クラブで「つい目を引かれて」と言います。彼女はほほえんで「ありがとう」と言いますが、友人たちのほうへ向き直ります。', '["肩をたたいて、会話を続けようとする", "やり取りにとどまるために、彼女の友人たちに自己紹介する", "すっきりと切り上げる。受け止めはしても乗ってこないのは、礼儀正しいお断り"]'::jsonb, 'ほほえんで向き直るのは、礼儀正しいお断りです。サインのあとも居座るのは、相手の反応に合わせられていない証拠です。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('702ce88e-2efa-49c5-9ee5-e08ed426d983', 'ja', '好奇心を引くひと言は、なぜ効果的なのですか？', '["事実だけでなく、彼女の意見や視点を招くから", "予想のつく事実の質問よりも、面白いから", "彼女が自然と考えを持っている話題をつくるから", "上のすべて"]'::jsonb, '情報が欠けていると、脳はそれを埋めようとします。これを使って、注意を引きつけましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('722e2188-0d60-460b-8ec7-ca6850661d5a', 'ja', '彼女が、鮮やかな手描きのスマホケースを持っているのを見かけます。相手を引き込むひと言は、どれですか？', '["「かっこいいスマホケースですね」", "「センスがいいですね」", "「今、何時ですか？」", "「そのスマホケース、ご自分で作ったように見えますね」"]'::jsonb, '具体的な推測は、彼女が自分のこととして関わり、答えることを求めます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('727d61fb-ef06-4574-b2e1-63fb70f840c8', 'ja', 'しっかりした最初の空気づくりの、主な目的は何ですか？', '["感心させること", "断られる可能性をなくすこと", "興味を生むこと", "沈黙を避けること"]'::jsonb, '最初につくる空気は、好奇心と感情的な関わりを呼び起こすものであるべきです。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('732636f6-4948-4cf7-ab3c-1529a104b4c8', 'ja', 'たいてい切り上げどきを意味する反応は、どれですか？', '["ひと言だけの返事", "体をそむけること", "質問が返ってこないこと", "質問に答えること"]'::jsonb, '関心が離れている手がかりがいくつも重なったら、切り上げどきです。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('75d003ed-f14a-4b05-a68f-d5a813844935', 'ja', '最初のひと言のあと、彼女が自分の考えを熱心に話し始めます。次の動きはどれですか？', '["すぐにLINEを聞く", "まず自分の意見を話す", "すぐに別の話題に切り替える", "耳を傾け、彼女の見方に応える"]'::jsonb, '彼女の答えを広げることは、その手間に報い、会話の流れを保ちます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('761e81ae-f2b8-48ba-a7a0-a8ebe688a7e5', 'ja', '路上で声をかけます。ひと言かけると、彼女は歩くペースを落とし、ほほえんで、隣を歩きます。', '["こちらに応じる義務を感じている", "受け入れていて、自分から関わり続けることを選んでいる", "どちらともつかず、こちらが話し終えるのを待っている"]'::jsonb, 'こちらに合わせて動きを変えるのは、自分の意思で関わっている証拠です。そのまま続けましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('77d7bb74-c3e1-4044-bfb0-c36b1415c65e', 'ja', '礼儀なのか受け入れなのか分からないときでも、なぜサインを尊重するべきなのですか？', '["冷たいサインを押し切るより、礼儀のサインの段階で切り上げるほうがいいから", "不確かさを尊重することが、相手に合わせられる人だと示すから", "彼女の関心を「確かめたい」というこちらの欲求より、彼女の心地よさのほうが大切だから", "上のすべて"]'::jsonb, '迷ったときは、関心が低いほうのサインを尊重しましょう。彼女の心地よさを優先します。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('78cf663a-b29b-480e-a8ef-fe1997c76016', 'ja', '歩み寄って、「ご一緒してもいいですか？」と言います。「どうぞ」と言われますが、グループはそのまま自分たちの会話を続けます。', '["会話が途切れるのを待ってから、自己紹介をする", "注意をこちらに戻すために、冗談を言う", "切り上げる。自分の空気をつくる代わりに、相手の空気に入れてもらおうとしたから"]'::jsonb, '加わっていいかと尋ねると、相手の現実に入ることになります。中身のあるひと言で話しかけて、自分の空気をつくりましょう。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7b6ea2f2-5183-4215-9488-2a520d528b32', 'ja', '話す前の、落ち着いた親しみのあるアイコンタクトは、何をもたらしますか？', '["すぐに、強烈に惹かれる気持ちを生む", "彼女に、すばやい反応を強いる", "言葉を使わずに、前向きな意図を伝える", "近づいていることを、完全に隠す"]'::jsonb, '温かく親しみのあるまなざしは、彼女の神経系に「安全だ」と伝えて安心させます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7b879d11-d60e-408e-b0dd-18f2dc6a1bab', 'ja', '二人とも、空港で遅れている便を待っています。プレッシャーを減らす最初のひと言は、どれですか？', '["「お疲れのようですね。少し話しませんか？」", "「待っているあいだ用に、LINEを教えてもらえますか？」", "「遅れていても、魅力的ですね」", "「この遅れ、こたえますね。あとどれくらいかかるか、ご存じですか？」"]'::jsonb, 'その場で共有している体験が、会話を自然に始めさせてくれます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7d344225-54cf-45ff-b8bc-1f401a89453f', 'ja', 'リラックスした動きは、何を伝えますか？', '["今いるその場所に、自分はいていいと信じていること", "体が、緊張や居心地の悪さを発していないこと", "まさにこの場面での声のかけ方を、前に練習したことがあること"]'::jsonb, 'なめらかな動きは、心地よさと、「ここにいて当然」という感覚を伝えます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('7e53f4ec-68aa-4155-b6ff-8c9214acf8e2', 'ja', 'ストレートなひと言の、一番の弱みは何ですか？', '["特定の社交の場でしか、うまくいかないこと", "さりげないひと言よりも、話す技術が必要なこと", "彼女がすぐに惹かれなければ、やり取りがすぐに終わること"]'::jsonb, 'ストレートなひと言は、相手をすぐに「見きわめモード」にします。打ち解けるための緩衝材はありません。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('80d3365a-d883-4997-8988-b8010451c01d', 'ja', '声をかけると、彼女がすぐに一歩下がります。最も考えられる原因は何ですか？', '["近づきすぎたか、彼女の動きをふさいだ", "関心がなく、意図的に物理的な距離を取っている", "どこかへ行かなければならない"]'::jsonb, '身を引くのは、安全のための反射的な反応であって、意図的な判断ではありません。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('81df7422-a32e-4d7e-9ee5-03e32f5773ef', 'ja', '推測から入るひと言を効果的にしている心理的な仕組みは、どれですか？', '["どうしてそう見えたのかについて、好奇心を引き起こす", "彼女の自尊心をくすぐる", "断られるリスクを減らす"]'::jsonb, '推測は、こちらの見方への好奇心を呼び起こし、彼女の頭を会話に引きつけておきます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('862f73dc-ec2a-4136-a805-782b65c7eece', 'ja', 'たった一度の会話が、何につながる可能性がありますか？', '["思ってもみなかった友人関係、恋愛、あるいはチャンス", "何年たっても覚えている経験やエピソード", "人生で大切な存在になる誰かとの出会い", "上のすべて"]'::jsonb, '会話は、その瞬間をはるかに超えて広がる可能性を生むことがあります。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('884ee9cb-5bc8-4593-8032-1bb68fe20856', 'ja', '二人ともライブ会場にいます。さりげないひと言になるのは、どれですか？', '["このバンドやアーティストを前にも見たことがあるかを聞く", "人の多さや会場についてひと言言う", "音楽の趣味がいいと伝える"]'::jsonb, '共有している体験から離れずにいると、安心感が自然に育っていきます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
insert into public.question_translations (question_id, locale, question_text, options, explanation) values ('88ec90e6-280c-40aa-896c-018951f9446c', 'ja', '彼女が、見覚えのある表紙の本を読んでいます。好奇心が伝わるひと言は、どれですか？', '["「本をたくさん読みそうな方ですね」", "「それ、新しい版ですか？ここまで読んでみて、どうですか？」", "「いい選択ですね。頭が良さそうです」", "「ご一緒してもいいですか？」"]'::jsonb, '彼女の経験への好奇心は、下心なしに、本物のつながりを招きます。')
  on conflict (question_id, locale) do update set question_text = excluded.question_text, options = excluded.options, explanation = excluded.explanation;
commit;
